//! Production/development asset source (the `webview` feature only).
//!
//! `UiAssets` is a [`rust_embed::RustEmbed`] over `frontend/dist`:
//! debug builds resolve files from the filesystem at runtime (the
//! `mise run dev-ui` loop — vite writes `frontend/dist`, no rebuild
//! needed), release builds embed the files into the binary for the
//! offline single-artifact distribution shape.
//!
//! `frontend/dist` is generated by `vite build` (see `ui/`) plus
//! `ui/scripts/write-manifest.mjs`, which emits
//! [`crate::revision::MANIFEST_NAME`]. The directory is not tracked —
//! headless builds never need it; [`crate::revision::check_bundle`]
//! explains exactly what to run when it is absent.

use std::sync::Arc;

use ruviform_ui::{AssetSource, MapAssetSource};
use ruviform_ui_webview::EmbedAssets;

use crate::error::AssetError;

/// The embedded/filesystem frontend bundle (`frontend/dist`).
#[derive(rust_embed::RustEmbed)]
#[folder = "frontend/dist"]
struct UiAssets;

/// The app asset source — `rvf://app` lookups resolve into `UiAssets`.
#[must_use]
pub fn app_asset_source() -> Arc<dyn AssetSource> {
    EmbedAssets::<UiAssets>::shared()
}

/// A minimal generated shell that explains *why* the real bundle was
/// rejected — served instead of the (untrustworthy) bundle files so
/// the user sees the failure in-app and nothing mismatched is ever
/// delivered.
///
/// The page is self-contained (inline styles, no scripts) — the
/// frontend bundle's own code cannot be assumed safe here.
#[must_use]
pub fn error_asset_source(err: &AssetError) -> Arc<dyn AssetSource> {
    let page = format!(
        "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">\
         <title>Synvelis — asset error</title>\
         <meta http-equiv=\"Content-Security-Policy\" \
         content=\"default-src 'none'; style-src 'unsafe-inline'\">\
         <style>body{{font-family:system-ui,sans-serif;background:#1b1d21;\
         color:#e8e8ea;margin:0;display:flex;min-height:100vh;\
         align-items:center;justify-content:center}}\
         main{{max-width:36rem;padding:2rem}}h1{{font-size:1.25rem}}\
         code{{background:#2a2d33;padding:.15em .4em;border-radius:4px}}\
         .tag{{color:#f0a868;font-family:monospace}}</style></head><body>\
         <main><h1>Synvelis could not load its interface</h1>\
         <p class=\"tag\">{tag}</p><p>{detail}</p>\
         <p>Rebuild the frontend with <code>mise run build-ui</code> and \
         relaunch. If this persists, the installed bundle does not match \
         this binary's ruviform revision.</p></main></body></html>",
        tag = escape_html(err.kind().tag()),
        detail = escape_html(err.detail()),
    );
    Arc::new(MapAssetSource::new().with_asset("index.html", Some("text/html"), page.into_bytes()))
}

/// HTML-escapes the five characters that matter in text/attribute
/// contexts — the page must stay well-formed even for hostile detail
/// strings.
fn escape_html(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&#39;")
}
